/**
 * Invoices — see src/docs/be-mds/invoice_app_apis_guide.md.
 *
 * Invoices are generated by the backend only; the client never creates them.
 * Two triggers exist:
 *  - `enrollment` — a course-fee document per enrollment, on student creation.
 *  - `payment`    — a receipt, when a payment is created (or corrected to) successful.
 */

export type InvoiceType = "enrollment" | "payment";

export interface ApiInvoice {
  id: number;
  /** `INV-{year}-{seq}` — server generated. */
  invoice_number: string;
  type: InvoiceType;
  /** Human label, e.g. "Payment Receipt". */
  type_display?: string;
  enrollment: number | null;
  student: number | null;
  student_name?: string | null;
  payment: number | null;
  /** Snapshot of the course name when the document was generated. */
  course_name?: string | null;
  amount: string;
  total_paid_so_far: string;
  remaining_balance: string;
  /** R2 archive location — null when R2 is not configured. */
  pdf_url: string | null;
  pdf_key?: string | null;
  /** Populated once the email task runs; null means it has not been sent. */
  emailed_to: string | null;
  cc_emails: string[];
  sent_at: string | null;
  created_at: string;
}

/** Query params for GET /api/invoices/ and /api/students/{id}/invoices/. */
export interface InvoiceListParams {
  type?: InvoiceType;
  student?: number;
  enrollment?: number;
  created_at__gte?: string;
  created_at__lte?: string;
  ordering?: string;
  page?: number;
  page_size?: number;
}

/** POST /api/invoices/{id}/resend/ (admin only). */
export interface InvoiceResendResponse {
  detail: string;
  to: string;
}

/** Singleton config controlling who gets CC'd on every invoice email. */
export interface InvoiceEmailConfig {
  cc_emails: string[];
  subject_prefix: string;
  /** When false, CCs are skipped entirely. */
  is_active: boolean;
  updated_at?: string;
}

export type InvoiceEmailConfigPayload = Omit<InvoiceEmailConfig, "updated_at">;
